// Configure su número (con indicativo, sin +) y la apikey que CallMeBot le envía por WhatsApp.
// Para activar CallMeBot y obtener la apikey siga las instrucciones de https://www.callmebot.com (sección WhatsApp).
const PHONE = '573000000000';
const APIKEY = 'SU_APIKEY';

// Opcional: no reenviar las recuperaciones
// if (msg.payload.type === 'machine_online') return null;

const text = msg.payload.text || JSON.stringify(msg.payload);
msg.url = 'https://api.callmebot.com/whatsapp.php?phone=' + PHONE +
          '&text=' + encodeURIComponent(text) + '&apikey=' + APIKEY;
msg.method = 'GET';
delete msg.payload;
return msg;
